def _encode(vals, left, right, root):
    if root == -1:
        return []
    out = []
    q = [root]
    for x in q:
        if x == -1:
            out.append(-1)
        else:
            out.append(vals[x])
            q.append(left[x])
            q.append(right[x])
    while out and out[-1] == -1:
        out.pop()
    return out


def buildTree(preorder, inorder):
    n = len(preorder)
    if n == 0:
        return []
    pos = {v: i for i, v in enumerate(inorder)}
    left = [-1] * n
    right = [-1] * n
    # node id = index in preorder; a task is (preorder start, inorder start, size)
    stack = [(0, 0, n)]
    while stack:
        p, s, size = stack.pop()
        k = pos[preorder[p]] - s  # nodes in the left subtree
        if k > 0:
            left[p] = p + 1
            stack.append((p + 1, s, k))
        if size - 1 - k > 0:
            right[p] = p + 1 + k
            stack.append((p + 1 + k, s + k + 1, size - 1 - k))
    return _encode(preorder, left, right, 0)
